	('SQL_NOTES', 'ON', 'ON', 'COMPILE-TIME', 'ON', 'SESSION', 'BOOLEAN', 'If set to 1, the default, warning_count is incremented each time a Note warning is encountered. If set to 0, Note warnings are not recorded. mysqldump has outputs to set this variable to 0 so that no unnecessary increments occur when data is reloaded.', NULL, NULL, NULL, 'OFF,ON', 'NO', NULL),
	('INNODB_BUFFER_POOL_CHUNK_SIZE', NULL, '16777216', 'COMPILE-TIME', '134217728', 'GLOBAL', 'INT UNSIGNED', 'Size of a single memory chunk within each buffer pool instance for resizing buffer pool. Online buffer pool resizing happens at this granularity. 0 means disable resizing buffer pool.', '1048576', '2147483647', '1048576', NULL, 'YES', 'REQUIRED'),
