	('HAVE_SSL', NULL, 'DISABLED', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'If the server supports secure connections, will be set to YES, otherwise will be set to NO. If set to DISABLED, the server was compiled with TLS support, but was not started with TLS support (see the mysqld options). See also have_openssl.', NULL, NULL, NULL, NULL, 'YES', NULL),
	('DEFAULT_REGEX_FLAGS', '', '', 'COMPILE-TIME', '', 'SESSION', 'SET', 'Default flags for the regex library', NULL, NULL, NULL, 'DOTALL,DUPNAMES,EXTENDED,EXTRA,MULTILINE,UNGREEDY', 'NO', 'REQUIRED'),
	('RELAY_LOG_RECOVERY', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Enables automatic relay log recovery right after the database startup, which means that the IO Thread starts re-fetching from the master right after the last transaction processed.', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL'),
	('HISTOGRAM_TYPE', 'DOUBLE_PREC_HB', 'DOUBLE_PREC_HB', 'COMPILE-TIME', 'DOUBLE_PREC_HB', 'SESSION', 'ENUM', 'Specifies type of the histograms created by ANALYZE. Possible values are: SINGLE_PREC_HB - single precision height-balanced, DOUBLE_PREC_HB - double precision height-balanced.', NULL, NULL, NULL, 'SINGLE_PREC_HB,DOUBLE_PREC_HB', 'NO', 'REQUIRED'),
	('BINLOG_FORMAT', 'MIXED', 'MIXED', 'COMPILE-TIME', 'MIXED', 'SESSION', 'ENUM', 'What form of binary logging the master will use: either ROW for row-based binary logging, STATEMENT for statement-based binary logging, or MIXED. MIXED is statement-based binary logging except for those statements where only row-based is correct: those which involve user-defined functions (i.e. UDFs) or the UUID() function; for those, row-based binary logging is automatically used.', NULL, NULL, NULL, 'MIXED,STATEMENT,ROW', 'NO', 'REQUIRED'),
	('HAVE_COMPRESS', NULL, 'YES', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'If the zlib compression library is accessible to the server, this will be set to YES, otherwise it will be NO. The COMPRESS() and UNCOMPRESS() functions will only be available if set to YES.', NULL, NULL, NULL, NULL, 'YES', NULL),
	('ANALYZE_SAMPLE_PERCENTAGE', '100.000000', '100.000000', 'COMPILE-TIME', '100.000000', 'SESSION', 'DOUBLE', 'Percentage of rows from the table ANALYZE TABLE will sample to collect table statistics. Set to 0 to let MariaDB decide what percentage of rows to sample.', '0', '100', NULL, NULL, 'NO', 'REQUIRED'),
	('INNODB_USE_ATOMIC_WRITES', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'Enable atomic writes, instead of using the doublewrite buffer, for files on devices that supports atomic writes. To use this option one must use innodb_file_per_table=1, innodb_flush_method=O_DIRECT. This option only works on Linux with either FusionIO cards using the directFS filesystem or with Shannon cards using any file system.', NULL, NULL, NULL, 'OFF,ON', 'YES', 'NONE'),
	('KEEP_FILES_ON_CREATE', 'OFF', 'OFF', 'COMPILE-TIME', 'OFF', 'SESSION', 'BOOLEAN', 'Don\'t overwrite stale .MYD and .MYI even if no directory is specified', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL'),
	('PROXY_PROTOCOL_NETWORKS', NULL, '', 'COMPILE-TIME', '', 'GLOBAL', 'VARCHAR', 'Enable proxy protocol for these source networks. The syntax is a comma separated list of IPv4 and IPv6 networks. If the network doesn\'t contain mask, it is considered to be a single host. "*" represents all networks and must the only directive on the line. String "localhost" represents non-TCP local connections (Unix domain socket, Windows named pipe or shared memory).', NULL, NULL, NULL, NULL, 'NO', 'REQUIRED'),
	('FT_BOOLEAN_SYNTAX', NULL, '+ -><()~*:""&|', 'COMPILE-TIME', '+ -><()~*:""&|', 'GLOBAL', 'VARCHAR', 'List of operators for MATCH ... AGAINST ( ... IN BOOLEAN MODE)', NULL, NULL, NULL, NULL, 'NO', 'REQUIRED'),
	('INNODB_DOUBLEWRITE', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'Enable InnoDB doublewrite buffer (enabled by default). Disable with --skip-innodb-doublewrite.', NULL, NULL, NULL, 'OFF,ON', 'YES', 'NONE'),
	('SLAVE_DDL_EXEC_MODE', NULL, 'IDEMPOTENT', 'COMPILE-TIME', 'IDEMPOTENT', 'GLOBAL', 'ENUM', 'How replication events should be executed. Legal values are STRICT and IDEMPOTENT (default). In IDEMPOTENT mode, replication will not stop for DDL operations that are idempotent. This means that CREATE TABLE is treated as CREATE TABLE OR REPLACE and DROP TABLE is treated as DROP TABLE IF EXISTS.', NULL, NULL, NULL, 'STRICT,IDEMPOTENT', 'NO', 'REQUIRED'),
