	('RELAY_LOG_SPACE_LIMIT', NULL, '0', 'COMPILE-TIME', '0', 'GLOBAL', 'BIGINT UNSIGNED', 'Maximum space to use for all relay logs', '0', '18446744073709551615', '1', NULL, 'YES', 'REQUIRED'),
	('INNODB_STATS_MODIFIED_COUNTER', NULL, '0', 'COMPILE-TIME', '0', 'GLOBAL', 'BIGINT UNSIGNED', 'The number of rows modified before we calculate new statistics (default 0 = current limits)', '0', '18446744073709551615', '0', NULL, 'NO', 'REQUIRED'),
	('SKIP_PARALLEL_REPLICATION', 'OFF', NULL, 'COMPILE-TIME', 'OFF', 'SESSION ONLY', 'BOOLEAN', 'If set when a transaction is written to the binlog, parallel apply of that transaction will be avoided on a slave where slave_parallel_mode is not "aggressive". Can be used to avoid unnecessary rollback and retry for transactions that are likely to cause a conflict if replicated in parallel.', NULL, NULL, NULL, 'OFF,ON', 'NO', NULL),
	('BINLOG_OPTIMIZE_THREAD_SCHEDULING', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'Run fast part of group commit in a single thread, to optimize kernel thread scheduling. On by default. Disable to run each transaction in group commit in its own thread, which can be slower at very high concurrency. This option is mostly for testing one algorithm versus the other, and it should not normally be necessary to change it.', NULL, NULL, NULL, 'OFF,ON', 'YES', 'REQUIRED'),
	('PERFORMANCE_SCHEMA_MAX_DIGEST_LENGTH', NULL, '1024', 'COMPILE-TIME', '1024', 'GLOBAL', 'INT', 'Maximum length considered for digest text, when stored in performance_schema tables.', '0', '1048576', '1', NULL, 'YES', 'REQUIRED'),
	('ENCRYPT_BINLOG', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Encrypt binary logs (including relay logs)', NULL, NULL, NULL, 'OFF,ON', 'YES', 'OPTIONAL'),
