	('INNODB_PURGE_THREADS', NULL, '4', 'COMPILE-TIME', '4', 'GLOBAL', 'INT UNSIGNED', 'Purge threads can be from 1 to 32. Default is 4.', '1', '32', '0', NULL, 'YES', 'OPTIONAL'),
	('BIG_TABLES', 'OFF', 'OFF', 'COMPILE-TIME', 'OFF', 'SESSION', 'BOOLEAN', 'Old variable, which if set to 1, allows large result sets by saving all temporary sets to disk, avoiding \'table full\' errors. No longer needed, as the server now handles this automatically. sql_big_tables is a synonym.', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL'),
	('PROFILING', 'OFF', 'OFF', 'COMPILE-TIME', 'OFF', 'SESSION', 'BOOLEAN', 'If set to 1 (0 is default), statement profiling will be enabled. See SHOW PROFILES and SHOW PROFILE.', NULL, NULL, NULL, 'OFF,ON', 'NO', NULL),
	('RPL_SEMI_SYNC_SLAVE_TRACE_LEVEL', NULL, '32', 'COMPILE-TIME', '32', 'GLOBAL', 'INT UNSIGNED', 'The tracing level for semi-sync replication.', '0', '4294967295', '1', NULL, 'NO', 'REQUIRED'),
	('ARIA_PAGECACHE_BUFFER_SIZE', NULL, '134217728', 'COMPILE-TIME', '134217728', 'GLOBAL', 'BIGINT UNSIGNED', 'The size of the buffer used for index blocks for Aria tables. Increase this to get better index handling (for all reads and multiple writes) to as much as you can afford.', '131072', '18446744073709551615', '1', NULL, 'YES', 'REQUIRED'),
	('BINLOG_CACHE_SIZE', NULL, '32768', 'COMPILE-TIME', '32768', 'GLOBAL', 'BIGINT UNSIGNED', 'The size of the transactional cache for updates to transactional engines for the binary log. If you often use transactions containing many statements, you can increase this to get more performance', '4096', '18446744073709551615', '4096', NULL, 'NO', 'REQUIRED'),
	('EXPENSIVE_SUBQUERY_LIMIT', '100', '100', 'COMPILE-TIME', '100', 'SESSION', 'BIGINT UNSIGNED', 'The maximum number of rows a subquery may examine in order to be executed during optimization and used for constant optimization', '0', '18446744073709551615', '1', NULL, 'NO', 'REQUIRED'),
	('PERFORMANCE_SCHEMA_MAX_FILE_HANDLES', NULL, '32768', 'COMPILE-TIME', '32768', 'GLOBAL', 'INT UNSIGNED', 'Maximum number of opened instrumented files.', '0', '1048576', '1', NULL, 'YES', 'REQUIRED'),
	('INNODB_BUFFER_POOL_DUMP_AT_SHUTDOWN', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'Dump the buffer pool into a file named @@innodb_buffer_pool_filename', NULL, NULL, NULL, 'OFF,ON', 'NO', 'REQUIRED'),
	('GTID_BINLOG_POS', NULL, '', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'Last GTID logged to the binary log, per replicationdomain', NULL, NULL, NULL, NULL, 'YES', NULL),
