	('DEADLOCK_SEARCH_DEPTH_LONG', '15', '15', 'COMPILE-TIME', '15', 'SESSION', 'INT UNSIGNED', 'Long search depth for the two-step deadlock detection', '0', '33', '1', NULL, 'NO', 'REQUIRED'),
	('REPLICATE_DO_TABLE', NULL, '', 'COMPILE-TIME', '', 'GLOBAL', 'VARCHAR', 'Tells the slave to restrict replication to tables in the comma-separated list.', NULL, NULL, NULL, NULL, 'NO', NULL),
	('MRR_BUFFER_SIZE', '262144', '262144', 'COMPILE-TIME', '262144', 'SESSION', 'INT UNSIGNED', 'Size of buffer to use when using MRR with range access', '8192', '2147483647', '1', NULL, 'NO', 'REQUIRED'),
	('EXTRA_MAX_CONNECTIONS', NULL, '1', 'COMPILE-TIME', '1', 'GLOBAL', 'INT UNSIGNED', 'The number of connections on extra-port', '1', '100000', '1', NULL, 'NO', 'REQUIRED'),
