	('INNODB_STATS_AUTO_RECALC', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'InnoDB automatic recalculation of persistent statistics enabled for all tables unless overridden at table level (automatic recalculation is only done when InnoDB decides that the table has changed too much and needs a new statistics)', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL'),
	('TCP_KEEPALIVE_INTERVAL', NULL, '0', 'COMPILE-TIME', '0', 'GLOBAL', 'INT', 'The interval, in seconds, between when successive keep-alive packets are sent if no acknowledgement is received.If set to 0, system dependent default is used.', '0', '2147483', '1', NULL, 'NO', 'REQUIRED'),
	('INNODB_COMMIT_CONCURRENCY', NULL, '0', 'COMPILE-TIME', '0', 'GLOBAL', 'INT UNSIGNED', 'Helps in performance tuning in heavily concurrent environments.', '0', '1000', '0', NULL, 'NO', 'REQUIRED'),
