	('INNODB_CONCURRENCY_TICKETS', NULL, '5000', 'COMPILE-TIME', '5000', 'GLOBAL', 'INT UNSIGNED', 'Number of times a thread is allowed to enter InnoDB within the same SQL query after it has once got the ticket', '1', '4294967295', '0', NULL, 'NO', 'REQUIRED'),
	('MAX_LONG_DATA_SIZE', NULL, '1048576', 'AUTO', '1048576', 'GLOBAL', 'INT UNSIGNED', 'The maximum BLOB length to send to server from mysql_send_long_data API. Deprecated option; use max_allowed_packet instead.', '1024', '4294967295', '1', NULL, 'YES', 'REQUIRED'),
	('INNODB_FATAL_SEMAPHORE_WAIT_THRESHOLD', NULL, '600', 'COMPILE-TIME', '600', 'GLOBAL', 'INT UNSIGNED', 'Maximum number of seconds that semaphore times out in InnoDB.', '1', '4294967295', '0', NULL, 'YES', 'REQUIRED'),
	('INNODB_BUFFER_POOL_LOAD_ABORT', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Abort a currently running load of the buffer pool', NULL, NULL, NULL, 'OFF,ON', 'NO', 'REQUIRED'),
	('INNODB_IDLE_FLUSH_PCT', NULL, '100', 'COMPILE-TIME', '100', 'GLOBAL', 'INT UNSIGNED', 'Up to what percentage of dirty pages should be flushed when innodb finds it has spare resources to do so.', '0', '100', '0', NULL, 'NO', 'REQUIRED'),
	('SQL_LOG_OFF', 'OFF', 'OFF', 'COMPILE-TIME', 'OFF', 'SESSION', 'BOOLEAN', 'If set to 1 (0 is the default), no logging to the general query log is done for the client. Only clients with the SUPER privilege can update this variable.', NULL, NULL, NULL, 'OFF,ON', 'NO', NULL),
	('INNODB_FT_SORT_PLL_DEGREE', NULL, '2', 'COMPILE-TIME', '2', 'GLOBAL', 'INT UNSIGNED', 'InnoDB Fulltext search parallel sort degree, will round up to nearest power of 2 number', '1', '16', '0', NULL, 'YES', 'REQUIRED'),
	('SLAVE_TRANSACTION_RETRY_INTERVAL', NULL, '0', 'COMPILE-TIME', '0', 'GLOBAL', 'INT UNSIGNED', 'Interval of the slave SQL thread will retry a transaction in case it failed with a deadlock or elapsed lock wait timeout or listed in slave_transaction_retry_errors', '0', '3600', '1', NULL, 'NO', 'REQUIRED'),
	('SESSION_TRACK_TRANSACTION_INFO', 'OFF', 'OFF', 'COMPILE-TIME', 'OFF', 'SESSION', 'ENUM', 'Track changes to the transaction attributes. OFF to disable; STATE to track just transaction state (Is there an active transaction? Does it have any data? etc.); CHARACTERISTICS to track transaction state and report all statements needed to start a transaction with the same characteristics (isolation level, read only/read write,snapshot - but not any work done / data modified within the transaction).', NULL, NULL, NULL, 'OFF,STATE,CHARACTERISTICS', 'NO', 'REQUIRED'),
	('LICENSE', NULL, 'GPL', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'The type of license the server has', NULL, NULL, NULL, NULL, 'YES', NULL),
