	('INNODB_ADAPTIVE_FLUSHING', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'Attempt flushing dirty pages to avoid IO bursts at checkpoints.', NULL, NULL, NULL, 'OFF,ON', 'NO', 'NONE'),
	('GTID_BINLOG_STATE', NULL, '', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'The internal GTID state of the binlog, used to keep track of all GTIDs ever logged to the binlog.', NULL, NULL, NULL, NULL, 'NO', NULL),
	('INNODB_FILE_PER_TABLE', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'Stores each InnoDB table to an .ibd file in the database dir.', NULL, NULL, NULL, 'OFF,ON', 'NO', 'NONE'),
	('RPL_SEMI_SYNC_MASTER_TRACE_LEVEL', NULL, '32', 'COMPILE-TIME', '32', 'GLOBAL', 'INT UNSIGNED', 'The tracing level for semi-sync replication.', '0', '4294967295', '1', NULL, 'NO', 'REQUIRED'),
	('EXTRA_PORT', NULL, '0', 'COMPILE-TIME', '0', 'GLOBAL', 'INT UNSIGNED', 'Extra port number to use for tcp connections in a one-thread-per-connection manner. 0 means don\'t use another port', '0', '4294967295', '1', NULL, 'YES', 'REQUIRED'),
	('GTID_STRICT_MODE', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Enforce strict seq_no ordering of events in the binary log. Slave stops with an error if it encounters an event that would cause it to generate an out-of-order binlog if executed.', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL'),
	('ARIA_BLOCK_SIZE', NULL, '8192', 'COMPILE-TIME', '8192', 'GLOBAL', 'INT UNSIGNED', 'Block size to be used for Aria index pages.', '4096', '32768', '1024', NULL, 'YES', 'REQUIRED'),
	('SLAVE_TRANSACTION_RETRY_ERRORS', NULL, '1158,1159,1160,1161,1205,1213,1429,2013,12701', 'COMPILE-TIME', '', 'GLOBAL', 'VARCHAR', 'Tells the slave thread to retry transaction for replication when a query event returns an error from the provided list. Deadlock error, elapsed lock wait timeout, net read error, net read timeout, net write error, net write timeout, connect error and 2 types of lost connection error are automatically added to this list', NULL, NULL, NULL, NULL, 'YES', 'REQUIRED'),
	('THREAD_POOL_PRIO_KICKUP_TIMER', NULL, '1000', 'COMPILE-TIME', '1000', 'GLOBAL', 'INT UNSIGNED', 'The number of milliseconds before a dequeued low-priority statement is moved to the high-priority queue', '0', '4294967295', '1', NULL, 'NO', 'REQUIRED'),
	('LOG_OUTPUT', NULL, 'FILE', 'COMPILE-TIME', 'FILE', 'GLOBAL', 'SET', 'How logs should be written', NULL, NULL, NULL, 'NONE,FILE,TABLE', 'NO', 'REQUIRED'),
