	('LARGE_PAGE_SIZE', NULL, '0', 'COMPILE-TIME', NULL, 'GLOBAL', 'INT UNSIGNED', 'If large page support is enabled, this shows the size of memory pages', '0', '4294967295', '1', NULL, 'YES', NULL),
	('INNODB_READ_IO_THREADS', NULL, '4', 'COMPILE-TIME', '4', 'GLOBAL', 'INT UNSIGNED', 'Number of background read I/O threads in InnoDB.', '1', '64', '0', NULL, 'YES', 'REQUIRED'),
	('SYSTEM_TIME_ZONE', NULL, 'America/New_York', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'The server system time zone', NULL, NULL, NULL, NULL, 'YES', NULL),
	('INNODB_WRITE_IO_THREADS', NULL, '4', 'COMPILE-TIME', '4', 'GLOBAL', 'INT UNSIGNED', 'Number of background write I/O threads in InnoDB.', '1', '64', '0', NULL, 'YES', 'REQUIRED'),
	('SLAVE_TRANSACTION_RETRIES', NULL, '10', 'COMPILE-TIME', '10', 'GLOBAL', 'INT UNSIGNED', 'Number of times the slave SQL thread will retry a transaction in case it failed with a deadlock, elapsed lock wait timeout or listed in slave_transaction_retry_errors, before giving up and stopping', '0', '4294967295', '1', NULL, 'NO', 'REQUIRED'),
	('INNODB_BUFFER_POOL_INSTANCES', NULL, '1', 'COMPILE-TIME', '0', 'GLOBAL', 'INT UNSIGNED', 'Number of buffer pool instances, set to higher value on high-end machines to increase scalability', '0', '64', '0', NULL, 'YES', 'REQUIRED'),
	('SECURE_TIMESTAMP', NULL, 'NO', 'COMPILE-TIME', 'NO', 'GLOBAL', 'ENUM', 'Restricts direct setting of a session timestamp. Possible levels are: YES - timestamp cannot deviate from the system clock, REPLICATION - replication thread can adjust timestamp to match the master\'s, SUPER - a user with this privilege and a replication thread can adjust timestamp, NO - historical behavior, anyone can modify session timestamp', NULL, NULL, NULL, 'NO,SUPER,REPLICATION,YES', 'YES', 'REQUIRED'),
	('INNODB_UNDO_DIRECTORY', NULL, '.\\', 'COMPILE-TIME', '', 'GLOBAL', 'VARCHAR', 'Directory where undo tablespace files live, this path can be absolute.', NULL, NULL, NULL, NULL, 'YES', 'REQUIRED'),
	('AUTO_INCREMENT_INCREMENT', '1', '1', 'COMPILE-TIME', '1', 'SESSION', 'INT UNSIGNED', 'Auto-increment columns are incremented by this', '1', '65535', '1', NULL, 'NO', 'OPTIONAL'),
	('INNODB_DEFRAGMENT_FILL_FACTOR', NULL, '0.900000', 'COMPILE-TIME', '0.900000', 'GLOBAL', 'DOUBLE', 'A number between [0.7, 1] that tells defragmentation how full it should fill a page. Default is 0.9. Number below 0.7 won\'t make much sense.This variable, together with innodb_defragment_fill_factor_n_recs, is introduced so defragmentation won\'t pack the page too full and cause page split on the next insert on every page. The variable indicating more defragmentation gain is the one effective.', '0.7', '1', NULL, NULL, 'NO', 'REQUIRED'),
	('UNIQUE_CHECKS', 'ON', 'ON', 'COMPILE-TIME', 'ON', 'SESSION', 'BOOLEAN', 'If set to 1, the default, secondary indexes in InnoDB tables are performed. If set to 0, storage engines can (but are not required to) assume that duplicate keys are not present in input data. Set to 0 to speed up imports of large tables to InnoDB. The storage engine will still issue a duplicate key error if it detects one, even if set to 0.', NULL, NULL, NULL, 'OFF,ON', 'NO', NULL),
	('INNODB_FT_RESULT_CACHE_LIMIT', NULL, '2000000000', 'COMPILE-TIME', '2000000000', 'GLOBAL', 'BIGINT UNSIGNED', 'InnoDB Fulltext search query result cache limit in bytes', '1000000', '18446744073709551615', '0', NULL, 'NO', 'REQUIRED'),
