	('INNODB_LOG_CHECKSUMS', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'Whether to compute and require checksums for InnoDB redo log blocks', NULL, NULL, NULL, 'OFF,ON', 'NO', 'REQUIRED'),
	('LOG_SLAVE_UPDATES', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Tells the slave to log the updates from the slave thread to the binary log. You will need to turn it on if you plan to daisy-chain the slaves.', NULL, NULL, NULL, 'OFF,ON', 'YES', 'OPTIONAL'),
	('ARIA_SORT_BUFFER_SIZE', '268434432', '268434432', 'COMPILE-TIME', '268434432', 'SESSION', 'BIGINT UNSIGNED', 'The buffer that is allocated when sorting the index when doing a REPAIR or when creating indexes with CREATE INDEX or ALTER TABLE.', '4096', '18446744073709551615', '1', NULL, 'NO', 'REQUIRED'),
	('INNODB_DATA_FILE_PATH', NULL, 'ibdata1:10M:autoextend', 'CONFIG', 'ibdata1:12M:autoextend', 'GLOBAL', 'VARCHAR', 'Path to individual files and their sizes.', NULL, NULL, NULL, NULL, 'YES', 'REQUIRED'),
	('MYISAM_SORT_BUFFER_SIZE', '8388608', '8388608', 'CONFIG', '134216704', 'SESSION', 'BIGINT UNSIGNED', 'The buffer that is allocated when sorting the index when doing a REPAIR or when creating indexes with CREATE INDEX or ALTER TABLE', '4096', '18446744073709551615', '1', NULL, 'NO', 'REQUIRED'),
	('RPL_SEMI_SYNC_SLAVE_DELAY_MASTER', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Only write master info file when ack is needed.', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL'),
	('INNODB_OLD_BLOCKS_PCT', NULL, '37', 'COMPILE-TIME', '37', 'GLOBAL', 'INT UNSIGNED', 'Percentage of the buffer pool to reserve for \'old\' blocks.', '5', '95', '0', NULL, 'NO', 'REQUIRED'),
	('SKIP_EXTERNAL_LOCKING', NULL, 'ON', 'COMPILE-TIME', NULL, 'GLOBAL', 'BOOLEAN', 'Don\'t use system (external) locking', NULL, NULL, NULL, 'OFF,ON', 'YES', NULL),
	('MYISAM_REPAIR_THREADS', '1', '1', 'COMPILE-TIME', '1', 'SESSION', 'INT UNSIGNED', 'If larger than 1, when repairing a MyISAM table all indexes will be created in parallel, with one thread per index. The value of 1 disables parallel repair', '1', '4294967295', '1', NULL, 'NO', 'REQUIRED'),
	('THREAD_CONCURRENCY', NULL, '10', 'COMPILE-TIME', '10', 'GLOBAL', 'INT UNSIGNED', 'Permits the application to give the threads system a hint for the desired number of threads that should be run at the same time.This variable has no effect, and is deprecated. It will be removed in a future release.', '1', '512', '1', NULL, 'YES', 'REQUIRED'),
	('INNODB_FT_AUX_TABLE', NULL, '', 'COMPILE-TIME', '', 'GLOBAL', 'VARCHAR', 'FTS internal auxiliary table to be checked', NULL, NULL, NULL, NULL, 'NO', 'REQUIRED'),
	('ARIA_PAGECACHE_FILE_HASH_SIZE', NULL, '512', 'COMPILE-TIME', '512', 'GLOBAL', 'INT UNSIGNED', 'Number of hash buckets for open and changed files.  If you have a lot of Aria files open you should increase this for faster flush of changes. A good value is probably 1/10 of number of possible open Aria files.', '128', '16384', '1', NULL, 'YES', 'REQUIRED'),
	('LOG_SLOW_FILTER', 'admin,filesort,filesort_on_disk,filesort_priority_queue,full_join,full_scan,query_cache,query_cache_miss,tmp_table,tmp_table_on_disk', 'admin,filesort,filesort_on_disk,filesort_priority_queue,full_join,full_scan,query_cache,query_cache_miss,tmp_table,tmp_table_on_disk', 'COMPILE-TIME', 'admin,filesort,filesort_on_disk,filesort_priority_queue,full_join,full_scan,query_cache,query_cache_miss,tmp_table,tmp_table_on_disk', 'SESSION', 'SET', 'Log only certain types of queries to the slow log. If variable empty alll kind of queries are logged.  All types are bound by slow_query_time, except \'not_using_index\' which is always logged if enabled', NULL, NULL, NULL, 'admin,filesort,filesort_on_disk,filesort_priority_queue,full_join,full_scan,not_using_index,query_cache,query_cache_miss,tmp_table,tmp_table_on_disk', 'NO', 'REQUIRED'),
	('SLAVE_PARALLEL_MODE', NULL, 'conservative', 'COMPILE-TIME', 'conservative', 'GLOBAL', 'ENUM', 'Controls what transactions are applied in parallel when using --slave-parallel-threads. Possible values: "optimistic" tries to apply most transactional DML in parallel, and handles any conflicts with rollback and retry. "conservative" limits parallelism in an effort to avoid any conflicts. "aggressive" tries to maximise the parallelism, possibly at the cost of increased conflict rate. "minimal" only parallelizes the commit steps of transactions. "none" disables parallel apply completely.', NULL, NULL, NULL, 'none,minimal,conservative,optimistic,aggressive', 'NO', NULL),
	('SLAVE_TYPE_CONVERSIONS', NULL, '', 'COMPILE-TIME', '', 'GLOBAL', 'SET', 'Set of slave type conversions that are enabled. If the variable is empty, no conversions are allowed and it is expected that the types match exactly', NULL, NULL, NULL, 'ALL_LOSSY,ALL_NON_LOSSY', 'NO', 'REQUIRED'),
	('SKIP_SHOW_DATABASE', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Don\'t allow \'SHOW DATABASE\' commands', NULL, NULL, NULL, 'OFF,ON', 'YES', 'OPTIONAL'),
	('SESSION_TRACK_SCHEMA', 'ON', 'ON', 'COMPILE-TIME', 'ON', 'SESSION', 'BOOLEAN', 'Track changes to the default schema.', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL'),
	('AUTOCOMMIT', 'ON', 'ON', 'COMPILE-TIME', 'ON', 'SESSION', 'BOOLEAN', 'If set to 1, the default, all queries are committed immediately. If set to 0, they are only committed upon a COMMIT statement, or rolled back with a ROLLBACK statement. If autocommit is set to 0, and then changed to 1, all open transactions are immediately committed.', NULL, NULL, NULL, 'OFF,ON', 'NO', NULL),
	('THREAD_STACK', NULL, '299008', 'COMPILE-TIME', '299008', 'GLOBAL', 'BIGINT UNSIGNED', 'The stack size for each thread', '131072', '18446744073709551615', '1024', NULL, 'YES', 'REQUIRED'),
	('EQ_RANGE_INDEX_DIVE_LIMIT', '200', '200', 'COMPILE-TIME', '200', 'SESSION', 'INT UNSIGNED', 'The optimizer will use existing index statistics instead of doing index dives for equality ranges if the number of equality ranges for the index is larger than or equal to this number. If set to 0, index dives are always used.', '0', '4294967295', '1', NULL, 'NO', 'REQUIRED'),
	('INNODB_CHECKSUM_ALGORITHM', NULL, 'crc32', 'COMPILE-TIME', 'crc32', 'GLOBAL', 'ENUM', 'The algorithm InnoDB uses for page checksumming. Possible values are FULL_CRC32 for new files, always use CRC-32C; for old, see CRC32 below; STRICT_FULL_CRC32 for new files, always use CRC-32C; for old, see STRICT_CRC32 below; CRC32 write crc32, allow any of the other checksums to match when reading; STRICT_CRC32 write crc32, do not allow other algorithms to match when reading; INNODB write a software calculated checksum, allow any other checksums to match when reading; STRICT_INNODB write a software calculated checksum, do not allow other algorithms to match when reading; NONE write a constant magic number, do not do any checksum verification when reading (same as innodb_checksums=OFF); STRICT_NONE write a constant magic number, do not allow values other than that magic number when reading; Files updated when this option is set to crc32 or strict_crc32 will not be readable by MariaDB versions older than 10.0.4; new files created with full_crc32 are readable by MariaDB 10.4.3+', NULL, NULL, NULL, 'crc32,strict_crc32,innodb,strict_innodb,none,strict_none,full_crc32,strict_full_crc32', 'NO', 'REQUIRED'),
	('INNODB_FORCE_LOAD_CORRUPTED', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Force InnoDB to load metadata of corrupted table.', NULL, NULL, NULL, 'OFF,ON', 'YES', 'NONE'),
	('ARIA_LOG_PURGE_TYPE', NULL, 'immediate', 'COMPILE-TIME', 'immediate', 'GLOBAL', 'ENUM', 'Specifies how Aria transactional log will be purged', NULL, NULL, NULL, 'immediate,external,at_flush', 'NO', 'REQUIRED'),
	('INNODB_CHECKSUMS', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'DEPRECATED. Use innodb_checksum_algorithm=NONE instead of setting this to OFF. Enable InnoDB checksums validation (enabled by default). Disable with --skip-innodb-checksums.', NULL, NULL, NULL, 'OFF,ON', 'YES', 'NONE'),
	('MYSQL56_TEMPORAL_FORMAT', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'Use MySQL-5.6 (instead of MariaDB-5.3) format for TIME, DATETIME, TIMESTAMP columns.', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL'),
	('TRANSACTION_PREALLOC_SIZE', '4096', '4096', 'COMPILE-TIME', '4096', 'SESSION', 'INT UNSIGNED', 'Persistent buffer for transactions to be stored in binary log', '1024', '134217728', '1024', NULL, 'NO', 'REQUIRED'),
	('DATETIME_FORMAT', NULL, '%Y-%m-%d %H:%i:%s', 'COMPILE-TIME', '%Y-%m-%d %H:%i:%s', 'GLOBAL', 'VARCHAR', 'The DATETIME format (ignored)', NULL, NULL, NULL, NULL, 'YES', 'REQUIRED'),
	('VERSION_COMPILE_OS', NULL, 'Win64', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'Operating system that MariaDB was built on, for example debian-linux-gnu.', NULL, NULL, NULL, NULL, 'YES', NULL),
	('DEADLOCK_TIMEOUT_SHORT', '10000', '10000', 'COMPILE-TIME', '10000', 'SESSION', 'INT UNSIGNED', 'Short timeout for the two-step deadlock detection (in microseconds)', '0', '4294967295', '1', NULL, 'NO', 'REQUIRED'),
	('PROTOCOL_VERSION', NULL, '10', 'COMPILE-TIME', NULL, 'GLOBAL', 'INT UNSIGNED', 'The version of the client/server protocol used by the MariaDB server', '0', '4294967295', '1', NULL, 'YES', NULL),
	('TCP_KEEPALIVE_PROBES', NULL, '0', 'COMPILE-TIME', '0', 'GLOBAL', 'INT', 'The number of unacknowledged probes to send before considering the connection dead and notifying the application layer.If set to 0, system dependent default is used.', '0', '2147483', '1', NULL, 'NO', 'REQUIRED'),
	('SLOW_QUERY_LOG_FILE', NULL, 'desoft-slow.log', 'COMPILE-TIME', '', 'GLOBAL', 'VARCHAR', 'Log slow queries to given log file. Defaults logging to \'hostname\'-slow.log. Must be enabled to activate other slow log options', NULL, NULL, NULL, NULL, 'NO', 'REQUIRED'),
	('ARIA_GROUP_COMMIT', NULL, 'none', 'COMPILE-TIME', 'none', 'GLOBAL', 'ENUM', 'Specifies Aria group commit mode. Possible values are "none" (no group commit), "hard" (with waiting to actual commit), "soft" (no wait for commit (DANGEROUS!!!))', NULL, NULL, NULL, 'none,hard,soft', 'NO', 'REQUIRED'),
	('SESSION_TRACK_STATE_CHANGE', 'OFF', 'OFF', 'COMPILE-TIME', 'OFF', 'SESSION', 'BOOLEAN', 'Track changes to the session state.', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL'),
	('INNODB_LOG_FILE_SIZE', NULL, '5242880', 'CONFIG', '50331648', 'GLOBAL', 'BIGINT UNSIGNED', 'Size of each log file in a log group.', '1048576', '17592186044415', '65536', NULL, 'YES', 'REQUIRED'),
	('IDLE_READONLY_TRANSACTION_TIMEOUT', '0', '0', 'COMPILE-TIME', '0', 'SESSION', 'INT UNSIGNED', 'The number of seconds the server waits for read-only idle transaction', '0', '2147483', '1', NULL, 'NO', 'REQUIRED'),
	('TIME_ZONE', 'SYSTEM', 'SYSTEM', 'COMPILE-TIME', 'SYSTEM', 'SESSION', 'VARCHAR', 'The current time zone, used to initialize the time zone for a client when it connects. Set to SYSTEM by default, in which the client uses the system time zone value.', NULL, NULL, NULL, NULL, 'NO', NULL),
	('REPLICATE_EVENTS_MARKED_FOR_SKIP', NULL, 'REPLICATE', 'COMPILE-TIME', 'REPLICATE', 'GLOBAL', 'ENUM', 'Whether the slave should replicate events that were created with @@skip_replication=1 on the master. Default REPLICATE (no events are skipped). Other values are FILTER_ON_SLAVE (events will be sent by the master but ignored by the slave) and FILTER_ON_MASTER (events marked with @@skip_replication=1 will be filtered on the master and never be sent to the slave).', NULL, NULL, NULL, 'REPLICATE,FILTER_ON_SLAVE,FILTER_ON_MASTER', 'NO', 'REQUIRED'),
	('USERSTAT', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Enables statistics gathering for USER_STATISTICS, CLIENT_STATISTICS, INDEX_STATISTICS and TABLE_STATISTICS tables in the INFORMATION_SCHEMA', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL'),
	('INNODB_VERSION', NULL, '10.4.11', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'InnoDB version', NULL, NULL, NULL, NULL, 'YES', NULL),
	('SESSION_TRACK_SYSTEM_VARIABLES', 'autocommit,character_set_client,character_set_connection,character_set_results,time_zone', 'autocommit,character_set_client,character_set_connection,character_set_results,time_zone', 'COMPILE-TIME', 'autocommit,character_set_client,character_set_connection,character_set_results,time_zone', 'SESSION', 'VARCHAR', 'Track changes in registered system variables. ', NULL, NULL, NULL, NULL, 'NO', 'REQUIRED'),
	('INNODB_TABLE_LOCKS', 'ON', 'ON', 'COMPILE-TIME', 'ON', 'SESSION', 'BOOLEAN', 'Enable InnoDB locking in LOCK TABLES', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL'),
	('INNODB_PURGE_BATCH_SIZE', NULL, '300', 'COMPILE-TIME', '300', 'GLOBAL', 'INT UNSIGNED', 'Number of UNDO log pages to purge in one batch from the history list.', '1', '5000', '0', NULL, 'NO', 'OPTIONAL'),
	('INNODB_FORCE_PRIMARY_KEY', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Do not allow to create table without primary key (off by default)', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL'),
	('HISTOGRAM_SIZE', '254', '254', 'COMPILE-TIME', '254', 'SESSION', 'INT UNSIGNED', 'Number of bytes used for a histogram. If set to 0, no histograms are created by ANALYZE.', '0', '255', '1', NULL, 'NO', 'REQUIRED'),
	('TCP_NODELAY', 'ON', 'ON', 'COMPILE-TIME', 'ON', 'SESSION', 'BOOLEAN', 'Set option TCP_NODELAY (disable Nagle\'s algorithm) on socket', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL'),
	('REPLICATE_WILD_IGNORE_TABLE', NULL, '', 'COMPILE-TIME', '', 'GLOBAL', 'VARCHAR', 'Tells the slave thread to not replicate to the tables that match the given wildcard pattern.', NULL, NULL, NULL, NULL, 'NO', NULL),
	('INNODB_FT_TOTAL_CACHE_SIZE', NULL, '640000000', 'COMPILE-TIME', '640000000', 'GLOBAL', 'INT UNSIGNED', 'Total memory allocated for InnoDB Fulltext Search cache', '32000000', '1600000000', '0', NULL, 'YES', 'REQUIRED'),
	('REPLICATE_ANNOTATE_ROW_EVENTS', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'Tells the slave to write annotate rows events received from the master to its own binary log. Ignored if log_slave_updates is not set', NULL, NULL, NULL, 'OFF,ON', 'YES', 'OPTIONAL'),
	('SLAVE_DOMAIN_PARALLEL_THREADS', NULL, '0', 'COMPILE-TIME', '0', 'GLOBAL', 'INT UNSIGNED', 'Maximum number of parallel threads to use on slave for events in a single replication domain. When using multiple domains, this can be used to limit a single domain from grabbing all threads and thus stalling other domains. The default of 0 means to allow a domain to grab as many threads as it wants, up to the value of slave_parallel_threads.', '0', '16383', '1', NULL, 'NO', 'REQUIRED'),
	('USE_STAT_TABLES', 'PREFERABLY_FOR_QUERIES', 'PREFERABLY_FOR_QUERIES', 'COMPILE-TIME', 'PREFERABLY_FOR_QUERIES', 'SESSION', 'ENUM', 'Specifies how to use system statistics tables', NULL, NULL, NULL, 'NEVER,COMPLEMENTARY,PREFERABLY,COMPLEMENTARY_FOR_QUERIES,PREFERABLY_FOR_QUERIES', 'NO', 'REQUIRED'),
	('ENFORCE_STORAGE_ENGINE', '', '', 'COMPILE-TIME', NULL, 'SESSION', 'VARCHAR', 'Force the use of a storage engine for new tables', NULL, NULL, NULL, NULL, 'NO', NULL),
	('INNODB_FAST_SHUTDOWN', NULL, '1', 'COMPILE-TIME', '1', 'GLOBAL', 'INT UNSIGNED', 'Speeds up the shutdown process of the InnoDB storage engine. Possible values are 0, 1 (faster), 2 (crash-like), 3 (fastest clean).', '0', '3', '0', NULL, 'NO', 'OPTIONAL'),
	('INNODB_FT_ENABLE_DIAG_PRINT', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Whether to enable additional FTS diagnostic printout ', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL'),
	('INNODB_PURGE_RSEG_TRUNCATE_FREQUENCY', NULL, '128', 'COMPILE-TIME', '128', 'GLOBAL', 'INT UNSIGNED', 'Dictates rate at which UNDO records are purged. Value N means purge rollback segment(s) on every Nth iteration of purge invocation', '1', '128', '0', NULL, 'NO', 'OPTIONAL'),
	('HAVE_SYMLINK', NULL, 'NO', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'If symbolic link support is enabled, will be set to YES, otherwise will be set to NO. Required for the INDEX DIRECTORY and DATA DIRECTORY table options (see CREATE TABLE) and Windows symlink support. Will be set to DISABLED if the server is started with the --skip-symbolic-links option.', NULL, NULL, NULL, NULL, 'YES', NULL),
	('INNODB_SYNC_SPIN_LOOPS', NULL, '30', 'COMPILE-TIME', '30', 'GLOBAL', 'INT UNSIGNED', 'Count of spin-loop rounds in InnoDB mutexes (30 by default)', '0', '4294967295', '0', NULL, 'NO', 'REQUIRED'),
	('INNODB_STATS_PERSISTENT_SAMPLE_PAGES', NULL, '20', 'COMPILE-TIME', '20', 'GLOBAL', 'BIGINT UNSIGNED', 'The number of leaf index pages to sample when calculating persistent statistics (by ANALYZE, default 20)', '1', '18446744073709551615', '0', NULL, 'NO', 'REQUIRED'),
	('RAND_SEED2', '626264895', NULL, 'COMPILE-TIME', '0', 'SESSION ONLY', 'BIGINT UNSIGNED', 'Sets the internal state of the RAND() generator for replication purposes', '0', '4294967295', '1', NULL, 'NO', NULL),
	('INNODB_FLUSH_NEIGHBORS', NULL, '1', 'COMPILE-TIME', '1', 'GLOBAL', 'INT UNSIGNED', 'Set to 0 (don\'t flush neighbors from buffer pool), 1 (flush contiguous neighbors from buffer pool) or 2 (flush neighbors from buffer pool), when flushing a block', '0', '2', '0', NULL, 'NO', 'OPTIONAL');
